package edu.alliance.medislot.service;import edu.alliance.medislot.dao.*;import edu.alliance.medislot.exception.*;import edu.alliance.medislot.util.PasswordUtil;import java.sql.*;import java.util.regex.*;public class AuthService{private final UserDao dao=new UserDao();private static final Pattern EMAIL=Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");public UserDao.Account register(String n,String e,String p,String ph)throws ValidationException,ConflictException,SQLException{if(n==null||n.isBlank()||n.length()>100)throw new ValidationException("Enter your name.");if(e==null||!EMAIL.matcher(e.trim()).matches())throw new ValidationException("Enter a valid email.");if(p==null||p.length()<8||p.length()>100)throw new ValidationException("Password must be at least 8 characters.");return dao.create(n.trim(),e.trim().toLowerCase(),PasswordUtil.hash(p),"PATIENT",ph==null?"":ph.trim());}public UserDao.Account login(String e,String p)throws SQLException{if(e==null||p==null)return null;UserDao.Account a=dao.byEmail(e.trim());return a!=null&&PasswordUtil.verify(p,a.hash())?a:null;}}